import math


import torch


import torch.nn as nn


_INPUT_NORMALIZATION_MODE = "whiten"


def set_input_normalization_mode(mode):
    global _INPUT_NORMALIZATION_MODE
    if mode not in {"whiten", "standard"}:
        raise ValueError(f"Unsupported input normalization mode: {mode}")
    _INPUT_NORMALIZATION_MODE = mode


def get_input_normalization_mode():
    return _INPUT_NORMALIZATION_MODE


def z_score_params(X, eps=1e-5):
    """
    Implements z-score data normalization.

    Parameters:
        X (torch.Tensor)[*, k]: The un-normalized data.

    Keywords:
        eps (float): Small value for numerical stability.

    Returns:
        mu (torch.Tensor)[k]: The mean vector.
        sigma (torch.Tensor)[k]: The standard deviations.
    """
    sigma, mu = torch.std_mean(X, dim=0)
    return mu, sigma + eps


def whitening_params(X, eps=1e-5):
    """
    Implements ZCA data whitening.

    Parameters:
        X (torch.Tensor)[*, k]: The un-whitened data.

    Keywords:
        eps (float): Small value for numerical stability.

    Returns:
        ZCA_mean (torch.Tensor)[k]: The ZCA whitening mean.
        ZCA_cov (torch.Tensor)[k, k]: The ZCA whitening covariance.
    """
    X_mean = torch.mean(X, dim=0)
    X_centered = X - X_mean

    if _INPUT_NORMALIZATION_MODE == "standard":
        std = torch.sqrt(torch.mean(X_centered ** 2, dim=0)).clamp_min(eps)
        return X_mean, torch.diag(1.0 / std)

    Sigma = X_centered.t() @ X_centered / X.shape[0]
    U, S, _ = torch.svd(Sigma)
    ZCA_mean = X_mean
    ZCA_cov = U @ torch.diag(torch.sqrt(S + eps) ** -1) @ U.t()
    return ZCA_mean, ZCA_cov


def whiten(x, mu, Sigma):
    """
    Applies ZCA whitening using previously computed mu and Sigma.

    Parameters:
        x (torch.Tensor)[n, k]: The un-whitened data.
        mu (torch.Tensor)[k]: The previously computed ZCA whitening mean vector.
        Sigma (torch.Tensor)[k, k]: The previously computed ZCA whitening covariance matrix.

    Returns:
        x' (torch.Tensor)[n, k]: The whitened data.
    """
    if x is None:
        return None

    if mu is None or Sigma is None:
        return x

    device = x.device
    if mu.device != device:
        mu = mu.to(device)
    if Sigma.device != device:
        Sigma = Sigma.to(device)

    return (x - mu) @ Sigma


def z_score(X, mu, sigma):
    """
    Safe z-score normalization with device consistency.

    Parameters:
        X (torch.Tensor)[n, k]
        mu (torch.Tensor)[k] or None
        sigma (torch.Tensor)[k] or None

    Returns:
        (X - mu) / sigma, on the same device as X
        or X itself if mu/sigma are None
    """

    if X is None:
        return None

    # If z-scoring disabled → pass-through
    if mu is None or sigma is None:
        return X

    device = X.device

    # Move to same device as X
    if mu.device != device:
        mu = mu.to(device)
    if sigma.device != device:
        sigma = sigma.to(device)

    return (X - mu) / sigma


def inverse_z_score(X, sigma, mu=None):
    """
    Reverses z_score normalization using previously computed mu and sigma.
    """

    device = X.device

    # Move sigma and mu to same device as X (GPU/CPU safe)
    if sigma is not None and sigma.device != device:
        sigma = sigma.to(device)
    if mu is not None and mu.device != device:
        mu = mu.to(device)

    if mu is None:
        return (sigma ** 2).diag().repeat(X.shape[0], 1, 1).bmm(X)
    else:
        return sigma * X + mu


def mvn_logprob(mean, Variance, x):
    """
    Computes multivariate normal distribution logprob of a value.

    Parameters:
        mean (torch.Tensor)[n, *]: The mean vectors of the multivariate normal distribution.
        Variance (torch.Tensor)[n, *, *]: The covariance matrices of the multivariate normal distribution.
        x (torch.Tensor)[n, *]: The vectors whose logprob shall be computed.

    Returns:
        logprob (torch.Tensor)[n]: The logprob values.
    """
    p = x.shape[-1]
    assert mean.shape[-1] == p and Variance.shape[-1] == p and Variance.shape[-2] == p
    c = -.5 * Variance.logdet()
    c += -.5 * p * math.log(2 * math.pi)
    diff = (x - mean).unsqueeze(-1)
    logprob = -.5 * diff.transpose(-2, -1).bmm(Variance.inverse()).bmm(diff)
    return c + logprob.squeeze()


def mvn_entropy(Variance):
    """
    Computes multivariate normal distribution entropy.

    Parameters:
        Variance (torch.Tensor)[n, *, *]: The covariance matrices of the multivariate normal distribution.

    Returns:
        entropy (torch.Tensor)[n]: The entropy values.
    """
    p = Variance.shape[-1]
    assert Variance.shape[-2] == p
    c = .5 * p * (math.log(2 * math.pi) + 1)
    return c + .5 * Variance.logdet()


def mvt_logprob(nu, loc, Scale, x):
    """
    Computes multivariate Student-t distribution logprob of a value.

    Parameters:
        nu (torch.Tensor)[1]: The degree of freedom parameter of the distributions.
        loc (torch.Tensor)[n, *]: The location vectors of the multivariate Student-t distribution.
        Scale (torch.Tensor)[n, *, *]: The scale matrices of the multivariate Student-t distribution.
        x (torch.Tensor)[n, *]: The vectors whose logprob shall be computed.

    Returns:
        logprob (torch.Tensor)[n]: The logprob values.
    """
    p = x.shape[-1]
    assert nu.item() > 0
    assert loc.shape[-1] == p and Scale.shape[-1] == p and Scale.shape[-2] == p
    c = -.5 * Scale.logdet()
    c += torch.lgamma(.5 * (nu + p)) - torch.lgamma(.5 * nu)
    c += -.5 * p * (torch.log(nu) + math.log(math.pi))
    diff = (x - loc).unsqueeze(-1)
    logprob = -.5 * (nu + p) * torch.log(1 + (nu ** -1) * diff.transpose(-2, -1).bmm(Scale.inverse()).bmm(diff))
    return c + logprob.squeeze()


def mvt_entropy(nu, Scale):
    """
    Computes multivariate Student-t distribution entropy.

    Parameters:
        nu (torch.Tensor)[1]: The degree of freedom parameter of the distributions.
        Scale (torch.Tensor)[n, *, *]: The scale matrices of the multivariate Student-t distribution.

    Returns:
        entropy (torch.Tensor)[n]: The entropy values.
    """
    p = Scale.shape[-1]
    assert nu.item() > 0
    assert Scale.shape[-2] == p
    c = torch.lgamma(.5 * nu) - torch.lgamma(.5 * (nu + p))
    c += .5 * p * (torch.log(nu) + math.log(math.pi))
    c += .5 * (nu + p) * (torch.digamma(.5 * (nu + p)) - torch.digamma(.5 * nu))
    return c + .5 * Scale.logdet()


def get_activation(activation):
    """
    Translates name of an activation function into the corresponding PyTorch implementation.

    Parameters:
        activation (str): Name of the desired activation function.

    Returns:
        {0} (torch.nn.Module): PyTorch implementation of the activation function.
    """
    activation_dict = {
        'sigmoid': nn.Sigmoid,
        'relu': nn.ReLU,
        'softplus': nn.Softplus,
        'tanh': nn.Tanh,
        'leaky_relu': nn.LeakyReLU
    }
    try:
        return activation_dict[activation]
    except KeyError:
        print("Specified activation function is not implemented. "
              "Please choose one of the following: "
              "'sigmoid', 'relu', 'softplus', 'tanh', 'leaky_relu'")
        exit(1)



# Source: src/dkl/train.py
import csv


import os


import sys


import time


import warnings


from pathlib import Path


import gpytorch


import torch


import torch.nn as nn


from gpytorch.kernels import GridInterpolationKernel, RBFKernel, ScaleKernel, SpectralMixtureKernel


from gpytorch.means import ConstantMean


from gpytorch.settings import (
    cg_tolerance,
    cholesky_jitter,
    fast_pred_var,
    max_cg_iterations,
    max_cholesky_size,
    max_lanczos_quadrature_iterations,
    max_preconditioner_size,
    num_trace_samples,
)


from gpytorch.utils.grid import ScaleToBounds


def activation_cls(name: str) -> type[nn.Module]:
    lookup = {
        "relu": nn.ReLU,
        "leaky_relu": nn.LeakyReLU,
        "gelu": nn.GELU,
        "silu": nn.SiLU,
        "tanh": nn.Tanh,
    }
    key = name.strip().lower()
    if key not in lookup:
        raise ValueError(f"Unsupported activation={name!r}; choose one of {sorted(lookup)}")
    return lookup[key]


class FeatureExtractor(nn.Module):
    def __init__(self, input_dim: int, hidden_dims: list[int], feature_dim: int, activation: str):
        super().__init__()
        act = activation_cls(activation)
        layers: list[nn.Module] = []
        in_dim = input_dim
        for hidden_dim in hidden_dims:
            layers.append(nn.Linear(in_dim, hidden_dim))
            layers.append(act())
            in_dim = hidden_dim
        layers.append(nn.Linear(in_dim, feature_dim))
        self.net = nn.Sequential(*layers)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.net(x)


class DeepKernelGP(gpytorch.models.ExactGP):
    def __init__(
        self,
        train_x: torch.Tensor,
        train_y: torch.Tensor,
        likelihood: gpytorch.likelihoods.GaussianLikelihood,
        input_dim: int,
        hidden_dims: list[int],
        feature_dim: int,
        activation: str,
        kernel_type: str,
        grid_size: int,
        num_mixtures: int,
    ):
        super().__init__(train_x, train_y, likelihood)
        self.feature_extractor = FeatureExtractor(input_dim, hidden_dims, feature_dim, activation)
        self.scale_to_bounds = ScaleToBounds(-1.0, 1.0)
        self.mean_module = ConstantMean()

        kernel_key = kernel_type.strip().lower()
        if kernel_key == "rbf":
            base_kernel = RBFKernel(ard_num_dims=feature_dim)
        elif kernel_key == "sm":
            base_kernel = SpectralMixtureKernel(num_mixtures=num_mixtures, ard_num_dims=feature_dim)
        else:
            raise ValueError("kernel_type must be 'rbf' or 'sm'")

        self.covar_module = ScaleKernel(
            GridInterpolationKernel(base_kernel, grid_size=grid_size, num_dims=feature_dim)
        )

    def initialize_sm_from_initial_features(self, train_x: torch.Tensor, train_y: torch.Tensor) -> None:
        grid_kernel = self.covar_module.base_kernel
        base_kernel = grid_kernel.base_kernel
        if not isinstance(base_kernel, SpectralMixtureKernel):
            return
        self.train()
        with torch.no_grad():
            projected = self.scale_to_bounds(self.feature_extractor(train_x))
            base_kernel.initialize_from_data(projected, train_y)

    def forward(self, x: torch.Tensor) -> gpytorch.distributions.MultivariateNormal:
        projected_x = self.scale_to_bounds(self.feature_extractor(x))
        mean_x = self.mean_module(projected_x)
        covar_x = self.covar_module(projected_x)
        return gpytorch.distributions.MultivariateNormal(mean_x, covar_x)


class DKLExperiment:
    def __init__(
        self,
        input_dim: int,
        hidden_dims: list[int],
        feature_dim: int,
        activation: str,
        kernel_type: str,
        grid_size: int,
        num_mixtures: int,
        device: torch.device,
    ):
        self.input_dim = input_dim
        self.hidden_dims = hidden_dims
        self.feature_dim = feature_dim
        self.activation = activation
        self.kernel_type = kernel_type
        self.grid_size = grid_size
        self.num_mixtures = num_mixtures
        self.device = device
        self.model: DeepKernelGP | None = None
        self.likelihood: gpytorch.likelihoods.GaussianLikelihood | None = None
        self.input_mean: torch.Tensor | None = None
        self.input_cov: torch.Tensor | None = None
        self.output_mean: torch.Tensor | None = None
        self.output_std: torch.Tensor | None = None
        self.traces: dict[str, list[float]] = {}

    def _prepare_data(
        self,
        x_train: torch.Tensor,
        y_train: torch.Tensor,
        normalize_x: bool,
        normalize_y: bool,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        self.input_mean, self.input_cov = whitening_params(x_train) if normalize_x else (None, None)
        self.output_mean, self.output_std = z_score_params(y_train) if normalize_y else (None, None)
        x_train_norm = whiten(x_train, self.input_mean, self.input_cov)
        y_train_norm = z_score(y_train, self.output_mean, self.output_std)
        return x_train_norm, y_train_norm.squeeze(-1)

    def _gp_settings(self, cfg: dict):
        return (
            max_cholesky_size(int(cfg.get("max_cholesky_size", 0))),
            cg_tolerance(float(cfg.get("cg_tolerance", 1e-3))),
            max_cg_iterations(int(cfg.get("max_cg_iterations", 1000))),
            max_preconditioner_size(int(cfg.get("max_preconditioner_size", 10))),
            num_trace_samples(int(cfg.get("num_trace_samples", 10))),
            max_lanczos_quadrature_iterations(int(cfg.get("max_lanczos_quadrature_iterations", 20))),
            cholesky_jitter(float_value=float(cfg.get("cholesky_jitter", 1e-4))),
        )

    def fit(
        self,
        x_train: torch.Tensor,
        y_train: torch.Tensor,
        cfg: dict,
        normalize_x: bool,
        normalize_y: bool,
        x_test: torch.Tensor | None = None,
        y_test: torch.Tensor | None = None,
        epoch_csv_path: str | None = None,
        run=None,
        split_idx: int = 0,
    ) -> float:
        train_x, train_y = self._prepare_data(x_train, y_train, normalize_x, normalize_y)
        self.likelihood = gpytorch.likelihoods.GaussianLikelihood().to(self.device)
        self.model = DeepKernelGP(
            train_x=train_x,
            train_y=train_y,
            likelihood=self.likelihood,
            input_dim=self.input_dim,
            hidden_dims=self.hidden_dims,
            feature_dim=self.feature_dim,
            activation=self.activation,
            kernel_type=self.kernel_type,
            grid_size=self.grid_size,
            num_mixtures=self.num_mixtures,
        ).to(self.device)
        self.model.initialize_sm_from_initial_features(train_x, train_y)

        self.model.train()
        self.likelihood.train()
        optimizer = torch.optim.Adam(self.model.parameters(), lr=float(cfg.get("lr", 0.1)))
        mll = gpytorch.mlls.ExactMarginalLogLikelihood(self.likelihood, self.model).to(self.device)

        self.traces = {"objective": [], "train_rmse": [], "train_nll": [], "test_rmse": [], "test_nll": []}
        epochs = int(cfg.get("epochs", 40))
        disable_tqdm = bool(cfg.get("disable_tqdm", False))
        eval_every_epochs = max(1, int(cfg.get("eval_every_epochs", 1)))
        save_epoch_eval = epoch_csv_path is not None
        log_to_wandb = bool(cfg.get("log_to_wandb", False)) and run is not None

        csv_f = None
        csv_writer = None
        if epoch_csv_path is not None:
            os.makedirs(os.path.dirname(epoch_csv_path), exist_ok=True)
            csv_f = open(epoch_csv_path, "w", newline="")
            csv_writer = csv.writer(csv_f)
            csv_writer.writerow(["epoch", "train_objective", "train_rmse", "train_nll", "test_rmse", "test_nll"])

        iterator = range(1, epochs + 1)
        if not disable_tqdm:
            import tqdm

            iterator = tqdm.tqdm(iterator, desc="Epoch")

        t0 = time.perf_counter()
        settings = self._gp_settings(cfg)
        with settings[0], settings[1], settings[2], settings[3], settings[4], settings[5], settings[6]:
            for epoch in iterator:
                self.model.train()
                self.likelihood.train()
                optimizer.zero_grad()
                output = self.model(train_x)
                objective = -mll(output, train_y)
                objective.backward()
                optimizer.step()
                objective_value = float(objective.item())
                self.traces["objective"].append(objective_value)

                if log_to_wandb:
                    run.log({f"train/split_{split_idx}/objective": objective_value, "epoch": epoch})

                should_eval = save_epoch_eval and ((epoch % eval_every_epochs == 0) or epoch == epochs)
                should_log_eval = log_to_wandb and (epoch == 1 or epoch % max(1, epochs // 10) == 0 or epoch == epochs)
                if should_eval or should_log_eval:
                    tr_rmse, tr_nll = self.evaluate_full(
                        x_train,
                        y_train,
                        normalize_x=normalize_x,
                        batch_size=int(cfg.get("eval_batch_size", 2000)),
                    )
                    if x_test is not None and y_test is not None:
                        te_rmse, te_nll = self.evaluate_full(
                            x_test,
                            y_test,
                            normalize_x=normalize_x,
                            batch_size=int(cfg.get("eval_batch_size", 2000)),
                        )
                    else:
                        te_rmse, te_nll = float("nan"), float("nan")

                    self.traces["train_rmse"].append(float(tr_rmse))
                    self.traces["train_nll"].append(float(tr_nll))
                    self.traces["test_rmse"].append(float(te_rmse))
                    self.traces["test_nll"].append(float(te_nll))

                    if csv_writer is not None:
                        csv_writer.writerow([epoch, objective_value, tr_rmse, tr_nll, te_rmse, te_nll])
                        csv_f.flush()
                    if should_log_eval:
                        run.log(
                            {
                                f"train/split_{split_idx}/rmse": tr_rmse,
                                f"train/split_{split_idx}/nll": tr_nll,
                                f"test/split_{split_idx}/rmse": te_rmse,
                                f"test/split_{split_idx}/nll": te_nll,
                                "epoch": epoch,
                            }
                        )

        if csv_f is not None:
            csv_f.close()
        return time.perf_counter() - t0

    @torch.no_grad()
    def predict(self, x: torch.Tensor, normalize_x: bool) -> tuple[torch.Tensor, torch.Tensor]:
        if self.model is None or self.likelihood is None:
            raise RuntimeError("Model has not been fit yet.")
        self.model.eval()
        self.likelihood.eval()
        x_norm = whiten(x, self.input_mean, self.input_cov) if normalize_x else x
        settings = (
            max_cholesky_size(0),
            max_preconditioner_size(10),
            fast_pred_var(),
        )
        with settings[0], settings[1], settings[2]:
            pred = self.likelihood(self.model(x_norm))
        mean = pred.mean.unsqueeze(-1)
        variance = pred.variance.unsqueeze(-1).clamp_min(1e-12)
        if self.output_mean is not None and self.output_std is not None:
            mean = inverse_z_score(mean, self.output_std, self.output_mean)
            variance = variance * (self.output_std.to(variance.device) ** 2)
        return mean, variance.clamp_min(1e-12)

    @torch.no_grad()
    def evaluate_batch(self, x: torch.Tensor, y: torch.Tensor, normalize_x: bool) -> tuple[float, float]:
        mean, variance = self.predict(x, normalize_x=normalize_x)
        y_flat = y.squeeze(-1)
        mean_flat = mean.squeeze(-1)
        var_flat = variance.squeeze(-1).clamp_min(1e-12)
        rmse = torch.sqrt(torch.mean((mean_flat - y_flat) ** 2)).item()
        nll = (0.5 * (torch.log(2 * torch.pi * var_flat) + ((y_flat - mean_flat) ** 2) / var_flat)).mean().item()
        return float(rmse), float(nll)

    @torch.no_grad()
    def evaluate_full(self, x: torch.Tensor, y: torch.Tensor, normalize_x: bool, batch_size: int = 2000) -> tuple[float, float]:
        n = int(x.shape[0])
        rmse_sq_sum = 0.0
        nll_sum = 0.0
        for start in range(0, n, batch_size):
            end = min(start + batch_size, n)
            mean, variance = self.predict(x[start:end], normalize_x=normalize_x)
            y_flat = y[start:end].squeeze(-1)
            mean_flat = mean.squeeze(-1)
            var_flat = variance.squeeze(-1).clamp_min(1e-12)
            rmse_sq_sum += float(torch.sum((mean_flat - y_flat) ** 2).item())
            nll_values = 0.5 * (torch.log(2 * torch.pi * var_flat) + ((y_flat - mean_flat) ** 2) / var_flat)
            nll_sum += float(torch.sum(nll_values).item())
        denom = float(max(1, n))
        return (rmse_sq_sum / denom) ** 0.5, nll_sum / denom

    def save(self, path: str, cfg: dict) -> None:
        if self.model is None or self.likelihood is None:
            raise RuntimeError("Model has not been fit yet.")
        torch.save(
            {
                "model_state_dict": self.model.state_dict(),
                "likelihood_state_dict": self.likelihood.state_dict(),
                "config": cfg,
                "input_mean": self.input_mean,
                "input_cov": self.input_cov,
                "output_mean": self.output_mean,
                "output_std": self.output_std,
                "traces": self.traces,
            },
            path,
        )



# --- Experiment I/O: these helpers are intentionally local to every script. ---
def experiment_setup():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--data", default=CONFIG["data_path"])
    parser.add_argument("--output", default=CONFIG["output_root"], help="Exact run directory; defaults create a unique subdirectory")
    parser.add_argument("--device", default=CONFIG["device"])
    parser.add_argument("--epochs", type=int, help="Optional training-budget override for smoke tests")
    parser.add_argument("--learning-rate", type=float, help="Override the model learning rate")
    parser.add_argument("--repulsion-strength", type=float, help="Override repulsion coefficient for repulsive methods")
    parser.add_argument("--reuse-stage1", help="BDKN stage1.pt to reuse; deep ensemble only")
    args = parser.parse_args()
    cfg = dict(CONFIG)
    if args.learning_rate is not None:
        if not np.isfinite(args.learning_rate) or args.learning_rate <= 0: parser.error("Learning rate must be finite and positive")
        cfg["lr"] = args.learning_rate
    if args.repulsion_strength is not None:
        if "repulsion_strength" not in cfg: parser.error("This method does not use repulsion")
        if not np.isfinite(args.repulsion_strength) or args.repulsion_strength < 0: parser.error("Repulsion strength must be finite and nonnegative")
        cfg["repulsion_strength"] = args.repulsion_strength
    if args.epochs is not None:
        if args.epochs < 1: parser.error("--epochs must be positive")
        cfg["epochs"] = args.epochs
    cfg["device"] = ("cuda:0" if torch.cuda.is_available() else "cpu") if args.device == "auto" else args.device
    torch.set_num_threads(cfg["cpu_threads"])
    random.seed(cfg["seed"]); np.random.seed(cfg["seed"]); torch.manual_seed(cfg["seed"])
    if torch.cuda.is_available(): torch.cuda.manual_seed_all(cfg["seed"])
    data_path = Path(args.data)
    if not data_path.is_absolute(): data_path = ROOT / data_path
    if not data_path.is_file():
        raise FileNotFoundError(f"Missing {data_path}. Run: python generate_data.py")
    with np.load(data_path, allow_pickle=False) as archive:
        data = {k: archive[k] for k in archive.files}
    for name in ("x_train", "y_train", "x_test", "y_test", "x_grid", "f_grid"):
        if name not in data or data[name].ndim != 2 or data[name].shape[1] != 1 or not np.isfinite(data[name]).all():
            raise ValueError(f"Invalid dataset array: {name}")
    for x, y in (("x_train", "y_train"), ("x_test", "y_test"), ("x_grid", "f_grid")):
        if len(data[x]) != len(data[y]) or len(data[x]) < 2: raise ValueError(f"Invalid lengths: {x}, {y}")
    cfg["data_path"] = str(data_path.resolve())
    cfg["dataset_sha256"] = hashlib.sha256(data_path.read_bytes()).hexdigest()
    cfg["reuse_stage1"] = args.reuse_stage1
    output = Path(args.output)
    if not output.is_absolute(): output = ROOT / output
    if args.output == CONFIG["output_root"]:
        output = output / (METHOD + "_" + datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S_%f"))
    output.mkdir(parents=True, exist_ok=False)
    (output / "config.json").write_text(json.dumps(cfg, indent=2) + "\n")
    return cfg, data, output, torch.device(cfg["device"])


def array(value):
    if isinstance(value, torch.Tensor): value = value.detach().cpu().numpy()
    return np.asarray(value, dtype=np.float64).reshape(-1)


def gaussian_prediction(mean, variance):
    mean, variance = array(mean), array(variance)
    if not np.isfinite(variance).all() or np.any(variance <= 0):
        raise FloatingPointError("Nonpositive or nonfinite predictive variance")
    scale = np.sqrt(variance)
    return dict(mean=mean, scale=scale, lower=mean-1.959963984540054*scale,
                upper=mean+1.959963984540054*scale, family="gaussian", df=None)



def training_clock(device):
    """Wall time with CUDA synchronization, so queued GPU work is counted."""
    if torch.device(device).type == "cuda": torch.cuda.synchronize(device)
    return time.perf_counter()


def record_result(label, test, grid, data, output, cfg, seconds):
    """Score noisy held-out observations and save predictions in original units."""
    from scipy.stats import norm, t
    for prediction, n in ((test, len(data["x_test"])), (grid, len(data["x_grid"]))):
        for key in ("mean", "scale", "lower", "upper"):
            values = array(prediction[key]); prediction[key] = values
            if len(values) != n or not np.isfinite(values).all(): raise FloatingPointError(f"Invalid {label} {key}")
        if np.any(prediction["scale"] <= 0) or np.any(prediction["lower"] > prediction["upper"]):
            raise FloatingPointError(f"Invalid {label} interval/scale")
    target = data["y_test"].reshape(-1)
    distribution = norm if test["family"] == "gaussian" else t
    kwargs = {} if test["family"] == "gaussian" else {"df": test["df"]}
    nll = -distribution.logpdf(target, loc=test["mean"], scale=test["scale"], **kwargs).mean()
    metrics = dict(method=label, rmse=float(np.sqrt(np.mean((target-test["mean"])**2))), nll=float(nll),
                   predictive_family=test["family"], seconds=seconds, dataset_sha256=cfg["dataset_sha256"])
    metrics.update(training_seconds=cfg.get("_training_seconds"),
                   stage1_training_seconds=cfg.get("_stage1_training_seconds"),
                   stage2_training_seconds=cfg.get("_stage2_training_seconds"),
                   training_reused=cfg.get("_training_reused", False))
    if not np.isfinite([metrics["rmse"], metrics["nll"]]).all(): raise FloatingPointError(f"Nonfinite metrics: {label}")
    folder=output / label; folder.mkdir()
    (folder / "metrics.json").write_text(json.dumps(metrics, indent=2) + "\n")
    arrays={}
    for split,pred in (("test",test),("grid",grid)):
        for key in ("mean","scale","lower","upper"): arrays[split+"_"+key]=pred[key]
    arrays.update(x_test=data["x_test"], y_test=data["y_test"], x_grid=data["x_grid"],
                  f_grid=data["f_grid"], df=np.nan if test["df"] is None else test["df"])
    np.savez_compressed(folder / "predictions.npz", **arrays)
    fig,ax=plt.subplots(figsize=(8,4))
    draw_prediction(ax,label,grid,data,metrics)
    fig.tight_layout(); fig.savefig(folder / "prediction.png", dpi=180); plt.close(fig)
    print(f"{label}: RMSE={metrics['rmse']:.5f}, NLL={metrics['nll']:.5f}", flush=True)
    return metrics


def draw_prediction(ax, label, grid, data, metrics):
    x=data["x_grid"].reshape(-1)
    ax.fill_between(x,grid["lower"],grid["upper"],alpha=.22,label="95% predictive interval")
    ax.plot(x,grid["mean"],label="Prediction")
    ax.plot(x,data["f_grid"].reshape(-1),"k--",lw=1,label="True function")
    ax.scatter(data["x_train"],data["y_train"],s=9,c="black",alpha=.45,label="Training data")
    ax.set(xlabel="x",ylabel="y",title=f"{label} | RMSE {metrics['rmse']:.4f} | NLL {metrics['nll']:.4f}",xlim=(-1,1))
    ax.legend(fontsize=7)


def save_history(output, rows):
    if not rows: return
    with (output / "history.csv").open("w",newline="") as handle:
        writer=csv.DictWriter(handle,fieldnames=list(rows[0])); writer.writeheader(); writer.writerows(rows)


def finish(output, rows):
    (output / "metrics.json").write_text(json.dumps(rows,indent=2)+"\n")
    print(f"Saved {output}", flush=True)



# --- Training and comparison entrypoint ---

def main():
    cfg,data,output,device=experiment_setup()
    if cfg["reuse_stage1"]: raise ValueError("--reuse-stage1 is only for deep_ensemble")
    set_input_normalization_mode(cfg["x_norm_type"])
    tensors={k:torch.tensor(data[k],dtype=torch.float32,device=device) for k in ("x_train","y_train","x_test","x_grid")}
    model=DKLExperiment(1,[cfg["hidden_dim"]]*cfg["hidden_layers"],cfg["feature_dim"],cfg["activation"],
                        cfg["kernel_type"],cfg["grid_size"],cfg["num_mixtures"],device)
    start=time.perf_counter()
    fit_t0=training_clock(device)
    model.fit(tensors["x_train"],tensors["y_train"],cfg,cfg["normalize_x"],cfg["normalize_y"])
    cfg["_training_seconds"]=training_clock(device)-fit_t0
    def prediction(key):
        mean,var=model.predict(tensors[key],normalize_x=cfg["normalize_x"])
        return gaussian_prediction(mean,var)
    rows=[record_result(METHOD,prediction("x_test"),prediction("x_grid"),data,output,cfg,time.perf_counter()-start)]
    save_history(output,[dict(epoch=i+1,objective=v) for i,v in enumerate(model.traces['objective'])])
    model.save(str(output / "model.pt"),cfg); finish(output,rows)


if __name__ == "__main__":
    main()
